#include <iomanip>
#include <iostream>
#include <map>
#include <memory>
#include <string>

// ---- price_cache.h: all that the files using PriceCache see
class PriceCache {
public:
    PriceCache();
    ~PriceCache();
    void update(const std::string& symbol, double price);
    double last(const std::string& symbol) const;
    int symbols() const;

private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};

// ---- price_cache.cpp
struct PriceCache::Impl {
    std::map<std::string, double> lastPrice;
};

PriceCache::PriceCache() : impl_(std::make_unique<Impl>()) {}
PriceCache::~PriceCache() = default;

void PriceCache::update(const std::string& symbol, double price) {
    impl_->lastPrice[symbol] = price;
}

double PriceCache::last(const std::string& symbol) const {
    const auto it = impl_->lastPrice.find(symbol);
    return it == impl_->lastPrice.end() ? 0.0 : it->second;
}

int PriceCache::symbols() const { return static_cast<int>(impl_->lastPrice.size()); }

// ---- main.cpp
int main() {
    PriceCache cache;
    int n = 0;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        std::string symbol;
        double price = 0.0;
        std::cin >> symbol >> price;
        cache.update(symbol, price);
    }
    std::string query;
    std::cin >> query;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << query << ' ' << cache.last(query) << '\n';
    std::cout << "symbols " << cache.symbols() << '\n';
    std::cout << "sizeof(PriceCache) " << sizeof(PriceCache) << '\n';
    return 0;
}
